from typing import Dict
import math

def drift_tail(M: int, n: int, c: int) -> Dict[str, float]:
    """Exact fraction of seed pairs with |S_x - S_y| >= c versus the Chebyshev bound
    2 n (t - 1) / c^2 implied by the two-seed drift law."""
    units = [N for N in range(1, M) if math.gcd(N, M) == 1]
    phi = len(units)
    t = sum(1 for y in units if y * y % M == 1)
    sq = phi // t
    dist = {t * b - n: math.comb(n, b) * sq**b * (phi - sq)**(n - b) for b in range(n + 1)}
    hits = sum(ca * cb for a, ca in dist.items() for b, cb in dist.items() if abs(a - b) >= c)
    return {"exact": hits / phi**(2 * n), "chebyshev": min(1.0, 2 * n * (t - 1) / c**2)}

if __name__ == "__main__":
    for c in (4, 8, 12, 16):
        print(c, drift_tail(15, 3, c))
